create or replace function pg_temp.actor(n integer) returns void language plpgsql as $$begin perform set_config('request.jwt.claim.sub',case n when 1 then 'd1000000-0000-0000-0000-000000000001' when 2 then 'd1000000-0000-0000-0000-000000000002' when 3 then 'd1000000-0000-0000-0000-000000000003' when 4 then 'd1000000-0000-0000-0000-000000000004' when 5 then 'c1000000-0000-0000-0000-000000000003' when 6 then 'a1000000-0000-0000-0000-000000000005' when 7 then 'a1000000-0000-0000-0000-000000000006' else 'e1000000-0000-0000-0000-000000000001' end,true);end$$;
