create function pg_temp.finish_field(task uuid,worker integer) returns void language plpgsql as $$declare inspection uuid;response uuid;begin
 perform pg_temp.actor(worker);perform pg_temp.fc('progress',jsonb_build_object('task_id',task,'state','work_completed'));perform pg_temp.actor(3);perform pg_temp.fc('supervisor_verify',jsonb_build_object('task_id',task));inspection=pg_temp.qc('request',jsonb_build_object('task_id',task,'inspector_id','d1000000-0000-0000-0000-000000000004','scheduled_at',clock_timestamp()));response=pg_temp.checklist(task,'quality',4);perform pg_temp.qc('submit',jsonb_build_object('id',inspection,'submission_id',response,'findings','[]'::jsonb));perform pg_temp.actor(5);perform pg_temp.qc('decide',jsonb_build_object('id',inspection,'decision','approved'));response=pg_temp.checklist(task,'handover',worker);perform pg_temp.actor(3);perform pg_temp.fc('review_checklist',jsonb_build_object('task_id',task,'id',response,'approve',true));end$$;
